def de_bruijn_fkm(k, n):
    alphabet = list(range(k))
    a = [0] * (k * n)
    sequence = []

    def db(t, p):
        if t > n:
            if n % p == 0:
                for j in range(1, p + 1):
                    sequence.append(a[j])
        else:
            a[t] = a[t - p]
            db(t + 1, p)
            for j in range(a[t - p] + 1, k):
                a[t] = j
                db(t + 1, t)

    db(1, 1)
    return sequence

seq = de_bruijn_fkm(3, 6)
print(f"Length: {len(seq)}")

# Verify all 729 tuples appear exactly once
k, n = 3, 6
seen = {}
for i in range(len(seq)):
    tup = tuple(seq[i:i+n])
    if len(tup) < n:
        tup = tuple(seq[i:] + seq[:n - len(tup)])
    if tup in seen:
        print(f"DUPLICATE: {tup} at positions {seen[tup]} and {i}")
        break
    seen[tup] = i

print(f"Unique tuples: {len(seen)}")
print(f"All present: {len(seen) == k**n}")

# Also verify all values are in {0,1,2}
print(f"All values valid: {all(x in {0,1,2} for x in seq)}")

# Print the full sequence
print("Sequence:")
print(seq)
